-- Чотири вкладки блоку «Питання і відповіді».
--
-- Формулювання навмисно не медичні: тексти описують, що відчує клієнтка, і скрізь
-- ведуть до консультації замість того, щоб давати заочні рекомендації.
-- Вкладка «Протипоказання» — це перелік станів, за яких потрібна розмова з майстром,
-- а не діагностичний інструмент.

INSERT INTO faq (tab, question, answer, sort, is_published) VALUES

('faq', 'Чи буде боляче?',
 'Це питання ставлять частіше за всі інші. Перед процедурою наноситься анестезія, і більшість клієнток описують відчуття як дискомфорт, а не біль — тиск, вібрація, іноді поколювання.\n\nБагато хто засинає під час роботи. Якщо стане неприємно, ми зупиняємось у будь-який момент — про це домовляємось на березі.', 10, 1),

('faq', 'Чи буде виглядати неприродно?',
 'Природність — це те, заради чого я працюю мінімальними обсягами й починаю з ескізу.\n\nФорму ми малюємо на вашому обличчі звичайним олівцем, ви дивитесь на неї в дзеркало, і процедура не починається, поки ви не скажете, що це саме те. Ніхто нікуди не поспішає.\n\nМоя задача — делікатно підкреслити те, що у вас уже є, а не намалювати нове обличчя.', 20, 1),

('faq', 'Скільки тримається результат?',
 'Перманентний макіяж живе від року до трьох. Точний строк залежить від типу шкіри, обраного відтінку й того, як ви доглядаєте за собою на сонці.\n\nІн’єкційні процедури тримаються від кількох місяців до року — залежно від методики.\n\nНа консультації я називаю реальні строки для вашого випадку, а не середні по індустрії.', 30, 1),

('faq', 'Чи можна перекрити роботу іншого майстра?',
 'Найчастіше так. Іноді достатньо перекрити старий пігмент новим, іноді його спершу потрібно освітлити — це два різні сценарії за часом і вартістю.\n\nЩоб відповісти точно, мені треба побачити роботу. Надішліть фото в месенджер або приходьте на консультацію — скажу чесно, що вийде за один візит, а що потребуватиме двох.', 40, 1),

('faq', 'Скільки це коштує?',
 'Вартість залежить від процедури та препарату, а ціни на препарати прив’язані до курсу валют. Тому я не публікую прайс, який застаріє за місяць.\n\nЗалиште заявку або напишіть у месенджер — назву актуальну вартість саме для вашого запиту.', 50, 1),

('faq', 'Навіщо потрібна корекція?',
 'Пігмент приживається нерівномірно — це нормальна властивість шкіри, а не помилка майстра. Десь колір ляже щільніше, десь світліше.\n\nКорекція через 4–8 тижнів вирівнює насиченість і доводить форму. Вона оплачується окремо й коштує 50% від основної процедури.\n\nБез корекції результат теж буде, але саме вона робить його довговічним.', 60, 1),

('contra', 'Коли процедуру доведеться відкласти',
 'Вагітність і період годування груддю. Гострі запальні процеси й підвищена температура. Загострення хронічних захворювань. Герпес у активній фазі — губи в такому стані не працюємо.\n\nЦе тимчасові стани: коли вони минають, до процедури можна повертатися.', 10, 1),

('contra', 'Коли потрібна попередня розмова',
 'Цукровий діабет. Порушення згортання крові й приймання препаратів, що на нього впливають. Схильність до келоїдних рубців. Онкологічні захворювання в анамнезі. Автоімунні стани. Алергії на анестетики.\n\nЦе не автоматична відмова. Це означає, що на консультації ми детально обговоримо ваш випадок, і за потреби я попрошу висновок вашого лікаря.', 20, 1),

('contra', 'Що обов’язково сказати мені до процедури',
 'Про всі препарати, які ви приймаєте постійно. Про перенесені захворювання й операції. Про алергічні реакції — будь-які, навіть ті, що здаються дрібницею. Про попередні косметологічні процедури, особливо ін’єкційні, і коли саме вони були.\n\nНічого з цього не є приводом для відмови саме по собі. Але від цієї інформації залежить, як я побудую роботу — тому не приховуйте нічого.', 30, 1),

('contra', 'Хто ухвалює остаточне рішення',
 'Рішення ухвалюється на консультації, після огляду й розмови — не за списком в інтернеті.\n\nЯкщо я бачу, що процедура вам зараз не підходить, я скажу про це прямо і поясню чому. Відмовити — теж робота майстра.', 40, 1),

('prep', 'За два тижні до процедури',
 'Не робіть пілінги, лазерні й агресивні доглядові процедури в зоні роботи. Шкіра має підійти до процедури у спокійному стані.\n\nЯкщо плануєте відпустку на морі — краще спершу відпочити, а потім прийти. Свіжий засмаглий епідерміс і пігмент погано дружать.', 10, 1),

('prep', 'За добу',
 'Не вживайте алкоголь. Обмежте каву й енергетики — вони підвищують чутливість і посилюють кровоточивість.\n\nЯкщо приймаєте препарати, що розріджують кров, і їх можна тимчасово скасувати — обговоріть це заздалегідь зі своїм лікарем, не самостійно.', 20, 1),

('prep', 'У день процедури',
 'Приходьте зі звичним макіяжем або без нього — як зручно. Якщо ви щодня малюєте брови чи стрілки певної форми, зробіть це: мені буде корисно побачити, до чого ви звикли.\n\nПоїжте перед візитом. Процедура триває від сорока хвилин до півтори години, і сидіти голодною некомфортно.\n\nЗакладіть трохи більше часу, ніж вказано. Ескіз і обговорення форми — це теж частина роботи, і поспіх тут зайвий.', 30, 1),

('prep', 'Що взяти з собою',
 'Нічого спеціального. За бажанням — навушники: багато хто слухає музику або просто дрімає.\n\nЯкщо у вас є фото робіт, які вам подобаються, покажіть їх. Точну копію ми не зробимо — у вас інша анатомія, — але я зрозумію напрямок, який вам близький.', 40, 1),

('aftercare', 'Перші дні',
 'Ділянка буде трохи припухлою й яскравішою, ніж очікуваний результат. Це нормальний перебіг загоєння, а не помилка.\n\nНе мочіть зону перші дні. Не тріть і не розпарюйте. Утвориться тонка скоринка — вона має зійти сама.\n\nЗдирати її не можна ні в якому разі: разом зі скоринкою піде пігмент, і на цьому місці лишиться світла пляма.', 10, 1),

('aftercare', 'Перші два тижні',
 'Уникайте сауни, басейну й тривалого перебування на сонці. Не робіть пілінгів у зоні роботи.\n\nВикористовуйте засіб, який я дам вам після процедури, за схемою — вона проста, але її треба дотримуватись.\n\nПриблизно на п’ятий-сьомий день колір здасться майже зниклим. Це найтривожніший момент для клієнток і водночас найзвичайніша річ: пігмент проявиться назад до кінця другого тижня.', 20, 1),

('aftercare', 'Що вважати нормою',
 'Легка припухлість перші дні. Зміна відтінку — від яскравого до майже непомітного й назад. Дрібне лущення. Відчуття сухості.\n\nНенормально: наростаючий біль, сильне почервоніння, виділення, температура. Якщо бачите щось із цього — пишіть мені одразу, не чекайте планової корекції.', 30, 1),

('aftercare', 'Надалі',
 'Користуйтеся сонцезахисним засобом на зоні перманенту. Ультрафіолет — головна причина, через яку колір вигорає швидше за строк.\n\nПеред лазерними процедурами на обличчі попереджайте косметолога, що у вас перманентний макіяж.\n\nІ приходьте на корекцію через 4–8 тижнів — саме вона закріплює результат надовго.', 40, 1);
